import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.CWWEQfK7.js";const P=JSON.parse('{"title":"认识 Ershu：能力、边界和适用场景","description":"了解 Ershu 怎样把多个代码库整理成可供人和开发智能体使用的项目上下文。","frontmatter":{"page_id":"overview-what-is-ershu","title":"认识 Ershu：能力、边界和适用场景","description":"了解 Ershu 怎样把多个代码库整理成可供人和开发智能体使用的项目上下文。"},"headers":[],"relativePath":"overview/what-is-ershu.md","filePath":"overview/what-is-ershu.md","lastUpdated":1786289447000}'),l={name:"overview/what-is-ershu.md"};function d(o,t,h,s,u,n){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="认识-ershu-能力、边界和适用场景" tabindex="-1">认识 Ershu：能力、边界和适用场景 <a class="header-anchor" href="#认识-ershu-能力、边界和适用场景" aria-label="Permalink to &quot;认识 Ershu：能力、边界和适用场景&quot;">​</a></h1><p>Ershu 是一套自行部署的代码理解与上下文服务。它把一个项目下的多个 GitHub、GitLab 或受信任本地仓库作为整体分析，生成文档、检索索引和代码关系，再通过网页、HTTP API 与 MCP（模型上下文协议）提供结果。</p><p>MCP 是开发智能体读取外部工具和数据的一种标准接口。在 Ershu 中，它是只读查询入口，不负责修改仓库。</p><h2 id="一次分析会留下什么" tabindex="-1">一次分析会留下什么？ <a class="header-anchor" href="#一次分析会留下什么" aria-label="Permalink to &quot;一次分析会留下什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结果</th><th>用途</th><th>从哪里使用</th></tr></thead><tbody><tr><td>仓库树和文件事实</td><td>确认路径、文件类型和当前提交</td><td>网页、API、MCP</td></tr><tr><td>结构化项目文档</td><td>按主题理解模块与流程</td><td>网页、API、MCP</td></tr><tr><td>词法与语义索引</td><td>按名称、文本或含义查找代码</td><td>网页、API、MCP</td></tr><tr><td>知识关系</td><td>查看符号和文件之间的联系</td><td>网页、API、MCP</td></tr><tr><td>分析记录与检查点</td><td>跟踪阶段、用量、结果和失败位置</td><td>网页、API</td></tr></tbody></table><p>Worker 只通过受限的只读工具读取分析工作区，不执行仓库脚本。生成文档需要已经配置并启用的模型通道；确定性的仓库事实和部分索引流程不等同于模型生成。</p><h2 id="它怎样融入日常工作" tabindex="-1">它怎样融入日常工作？ <a class="header-anchor" href="#它怎样融入日常工作" aria-label="Permalink to &quot;它怎样融入日常工作？&quot;">​</a></h2><ol><li>管理员创建首个账号，配置模型通道和项目访问权限。</li><li>项目成员添加仓库，并先运行一次覆盖全部有效仓库的全项目分析。</li><li>Worker 在后台准备只读工作区，提取事实并生成项目级结果。</li><li>成员在网页阅读文档、搜索和查看关系；开发智能体通过受限 MCP 密钥查询同一项目。</li><li>后续仓库提交可以触发增量分析。Cron 轮询和签名 Webhook 都由 API 侧接收，实际分析仍交给 Worker。</li></ol><p>第一次分析必须是全项目分析。没有这份基线时，API 会拒绝增量任务，避免把局部结果误当成完整项目视图。</p><h2 id="哪些人适合使用" tabindex="-1">哪些人适合使用？ <a class="header-anchor" href="#哪些人适合使用" aria-label="Permalink to &quot;哪些人适合使用？&quot;">​</a></h2><ul><li>维护由多个仓库组成、需要统一项目视图的团队；</li><li>需要理解陌生代码、追踪实现来源或核对模块边界的开发者；</li><li>需要给开发智能体提供可控、可追溯上下文的负责人；</li><li>希望在自己的基础设施中保管仓库凭据、项目权限和模型设置的组织。</li></ul><h2 id="使用前要知道的边界" tabindex="-1">使用前要知道的边界 <a class="header-anchor" href="#使用前要知道的边界" aria-label="Permalink to &quot;使用前要知道的边界&quot;">​</a></h2><ul><li>当前项目需要自行部署，尚不能仅靠公开软件包完成全套安装；组合仓库和后端模块仍引用私有 Git 源。</li><li>Ershu 生成的是帮助理解代码的材料，不替代源码、测试和人工评审。来源冲突时应回到当前代码核对。</li><li><code>/health</code> 是进程存活检查，不代表所有外部依赖都已就绪。数据库、Milvus、模型通道和 Worker 需要分别确认。</li><li>API 创建任务后只会把任务放入队列；没有运行中的 Worker，任务不会完成。</li><li>语义检索依赖可用的 Milvus 和嵌入模型。语义模式失败时不会悄悄改成词法搜索；混合模式才可能明确报告回退。</li><li>本地仓库只允许管理员配置，并且路径必须进入受信任范围。</li></ul><p>如果这些前提符合你的环境，请继续阅读<a href="/configuration/">特性详解</a>；准备实际部署时，从<a href="/configuration/basic">基础配置</a>开始。</p><blockquote><p>事实来源：五个模块的入口、仓库结构类型、运行创建与队列测试、只读工具安全测试，以及 Ershu MCP 项目概览。</p></blockquote>',15)])])}const p=a(l,[["render",d]]);export{P as __pageData,p as default};
